HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inqsi ARB</title><style>body{font-family:system-ui;margin:0;color:#111}.w{max-width:1120px;margin:auto;padding:18px}.bar{display:flex;gap:10px;flex-wrap:wrap;align-items:end}input,button{padding:9px;border:1px solid #bbb;border-radius:8px}button{background:#111;color:#fff;font-weight:700}.s,.c{border:1px solid #ddd;border-radius:10px;padding:12px;margin-top:12px}.m{color:#666;font-size:12px}.leg{background:#f5f5f5;padding:8px;border-radius:8px;margin-top:6px}.pill{border:1px solid #bbb;border-radius:999px;padding:3px 7px;font-size:11px}</style></head><body><div class="w"><div class="bar"><h2>Inqsi ARB</h2><input id="sport" value="baseball_mlb"><input id="markets" value="h2h,spreads,totals"><input id="bankroll" type="number" value="1000"><button onclick="scan()">Scan</button></div><div id="status" class="s">Ready.</div><div id="out"></div></div><script>const api=location.origin+location.pathname.replace(/\/v1\/arb\/ui$/,'');const e=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));async function scan(){status.textContent='Scanning…';out.innerHTML='';let p=new URLSearchParams({sport:sport.value,markets:markets.value,bankroll:bankroll.value});try{let r=await fetch(api+'/v1/arb/scan?'+p),j=await r.json();status.textContent=(j.n_arbs||0)+' verified arbs · '+(j.n_markets||0)+' markets · '+(j.version||'');out.innerHTML=(j.hits||[]).map(x=>'<div class="c"><b>'+e(x.event)+'</b> <span class="pill">VERIFIED</span><div class="m">'+e(x.market)+' · '+Number(x.margin_pct||0).toFixed(2)+'%</div>'+(x.legs||[]).map(l=>'<div class="leg">'+e(l.outcome)+' · '+e(l.book)+' · '+e(l.american)+' · '+e(l.last_update||'timestamp unavailable')+'</div>').join('')+'</div>').join('')||'<div class="c">No verified arbitrage opportunities.</div>'}catch(err){status.textContent='Data unavailable: '+err.message}}</script></body></html>'''
